import { getAnalysisSource } from "../analysisSource";
import { startStatusPolling } from "../statusPolling";

export function useAnalysisSource() {
  const source = getAnalysisSource();
  const [, setPresentation] = useState(() => source.presentation());
  useEffect(() => startStatusPolling(async signal => {
    try { await source.refresh(undefined, signal); }
    finally { if (!signal.aborted && getAnalysisSource() === source) setPresentation(source.presentation()); }
  }), [source]);
  return source.presentation();
}
